    flex-shrink: 0;
    width: 38px;
    height: 38px;
    padding: 0;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 8px;
    background: rgba(0, 0, 0, 0.32);
    cursor: pointer;
}

.experiment-builder__color-picker::-webkit-color-swatch-wrapper {
    padding: 4px;
}

.experiment-builder__color-picker::-webkit-color-swatch {
    border-radius: 5px;
    border: none;
}

.experiment-builder__field-key {
    margin-bottom: 5px;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(170, 170, 180, 0.85);
}

.experiment-builder__checkbox {
    grid-column: 1 / -2;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-top: 4px;
    font-size: 0.82rem;
    color: rgba(200, 200, 210, 0.92);
    cursor: pointer;
}

.experiment-builder__checkbox input[type="checkbox"] {
    accent-color: rgba(192, 159, 83, 0.85);
    width: 16px;
    height: 16px;
}

.experiment-builder__remove {
    align-self: end;
    padding: 8px 12px;
    font-size: 0.78rem;
    font-family: inherit;
    color: rgba(220, 180, 180, 0.92);
    background: transparent;
    border: 1px solid rgba(220, 100, 100, 0.32);
    border-radius: 8px;
    cursor: pointer;
    transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}

.experiment-builder__remove:hover:not(:disabled),
.experiment-builder__remove:focus-visible:not(:disabled) {
    color: #fbe6e6;
    border-color: rgba(232, 95, 95, 0.65);
    background: rgba(232, 95, 95, 0.12);
}

.experiment-builder__remove:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.experiment-builder__variant-settings {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 12px;
    margin-top: 14px;
    padding: 12px 14px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.05);
    background: rgba(0, 0, 0, 0.18);
}

.experiment-builder__add {
    padding: 10px 16px;
    font-size: 0.84rem;
    font-weight: 600;
    font-family: inherit;
    color: rgba(220, 220, 230, 0.92);
    background: rgba(255, 255, 255, 0.04);
    border: 1px dashed rgba(255, 255, 255, 0.18);
    border-radius: 9px;
    cursor: pointer;
    transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}

.experiment-builder__add:hover,
.experiment-builder__add:focus-visible {
    color: #faf6ee;
    border-color: rgba(192, 159, 83, 0.5);
    background: rgba(192, 159, 83, 0.08);
}

.experiment-builder__split-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-wrap: wrap;
    gap: 8px 12px;
}

.experiment-builder__split-list li {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 6px 12px;
    font-size: 0.78rem;
    color: rgba(220, 220, 230, 0.92);
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 999px;
}

.experiment-builder__split-list code {
    font-size: 0.78rem;
    color: rgba(232, 220, 200, 0.95);
}

.experiment-builder__split-list span {
    font-variant-numeric: tabular-nums;
    color: rgba(192, 159, 83, 0.92);
    font-weight: 650;
}

.experiment-builder__errors {
    margin-bottom: 16px;
    padding: 12px 16px;
    border-radius: 10px;
    border: 1px solid rgba(232, 95, 95, 0.4);
    background: linear-gradient(
        155deg,
        rgba(232, 95, 95, 0.12) 0%,
        rgba(0, 0, 0, 0.22) 65%
    );
    color: rgba(255, 220, 220, 0.95);
    font-size: 0.82rem;
    line-height: 1.5;
}

.experiment-builder__errors strong {
    display: block;
    margin-bottom: 6px;
    color: rgba(255, 200, 200, 0.96);
}

.experiment-builder__errors ul {
    margin: 0;
    padding-left: 18px;
}

.experiment-builder__output-head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 8px 14px;
    margin-bottom: 8px;
}

.experiment-builder__copy {
    padding: 8px 16px;
    font-size: 0.82rem;
    font-weight: 650;
    font-family: inherit;
    color: #20180c;
    background: linear-gradient(
        165deg,
        rgba(216, 181, 106, 0.96) 0%,
        rgba(184, 141, 60, 0.96) 100%
    );
    border: 1px solid rgba(192, 159, 83, 0.55);
    border-radius: 9px;
    cursor: pointer;
    transition: filter 0.15s ease;
}

.experiment-builder__copy:hover:not(:disabled),
.experiment-builder__copy:focus-visible:not(:disabled) {
    filter: brightness(1.07);
}

.experiment-builder__copy:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.experiment-builder__copy--ok {
    color: #1a3a1a;
    background: linear-gradient(165deg, #a8d39c, #6fae62);
    border-color: rgba(150, 200, 130, 0.6);
}

.experiment-builder__copy--err {
    color: #fbe6e6;
    background: linear-gradient(165deg, rgba(232, 95, 95, 0.85), rgba(180, 60, 60, 0.85));
    border-color: rgba(232, 95, 95, 0.55);
}

.experiment-builder__snippet {
    margin: 0;
    padding: 16px 18px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(0, 0, 0, 0.42);
    color: #e8dcc8;
    font-family: ui-monospace, "SF Mono", Menlo, monospace;
    font-size: 0.78rem;
    line-height: 1.6;
    white-space: pre;
    overflow-x: auto;
    max-height: 360px;
    overflow-y: auto;
}

.experiment-builder__snippet code {
    background: none;
    border: none;
    padding: 0;
    color: inherit;
    font-size: inherit;
}

@media screen and (max-width: 720px) {
    .experiment-builder__variant-row {
        grid-template-columns: 1fr 1fr;
    }

    .experiment-builder__variant-row .experiment-builder__variant-field--narrow {
        max-width: none;
    }

    .experiment-builder__checkbox {
        grid-column: 1 / -1;
    }

    .experiment-builder__remove {
        grid-column: 1 / -1;
        justify-self: start;
    }
}

/* ---------------------------------------------------------------- */
/* Experiment summary strip                                         */
/* ---------------------------------------------------------------- */

.experiment-summary {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 18px;
    padding: 18px 22px;
    margin: 0 0 18px;
    background: linear-gradient(
        180deg,
        rgba(192, 159, 83, 0.08) 0%,
        rgba(22, 22, 26, 0.3) 100%
    );
    border: 1px solid rgba(192, 159, 83, 0.22);
    border-radius: 12px;
}

.experiment-summary__cell {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;
}

.experiment-summary__label {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(192, 159, 83, 0.85);
    font-weight: 600;
}

.experiment-summary__value {
    font-size: 22px;
    font-weight: 700;
    color: #f3f3f3;
    line-height: 1.15;
    letter-spacing: -0.01em;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.experiment-summary__value--leader {
    color: #f5d27a;
}

.experiment-summary__sub {
    font-size: 12px;
    color: #a4a4a8;
    line-height: 1.35;
}

.experiment-summary__cell--leader {
    border-left: 1px solid rgba(192, 159, 83, 0.18);
    padding-left: 18px;
}

.experiment-summary__confidence {
    margin-top: 6px;
    align-self: flex-start;
    display: inline-flex;
    align-items: center;
    padding: 3px 8px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.02em;
}

.experiment-summary__confidence--high {
    background: rgba(76, 175, 80, 0.18);
    color: #8de08e;
    border: 1px solid rgba(76, 175, 80, 0.4);
}

.experiment-summary__confidence--mid {
    background: rgba(255, 152, 0, 0.18);
    color: #ffc97a;
    border: 1px solid rgba(255, 152, 0, 0.4);
}

.experiment-summary__confidence--low {
    background: rgba(158, 158, 158, 0.18);
    color: #c4c4c4;
    border: 1px solid rgba(158, 158, 158, 0.35);
}

@media screen and (max-width: 720px) {
    .experiment-summary {
        padding: 14px 16px;
    }

    .experiment-summary__value {
        font-size: 19px;
    }

    .experiment-summary__cell--leader {
        border-left: none;
        padding-left: 0;
        border-top: 1px solid rgba(192, 159, 83, 0.18);
        padding-top: 12px;
    }
}

/* ---------------------------------------------------------------- */
/* Sort + view toolbar                                              */
/* ---------------------------------------------------------------- */

.experiments-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
    margin: 0 0 14px;
    padding: 10px 14px;
    background: rgba(22, 22, 26, 0.55);
    border: 1px solid rgba(192, 159, 83, 0.14);
    border-radius: 10px;
}

.experiments-toolbar__field {
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.experiments-toolbar__label {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(192, 159, 83, 0.85);
    font-weight: 600;
}

.experiments-toolbar__select {
    background: rgba(34, 34, 40, 0.95);
    color: #ececec;
    border: 1px solid rgba(192, 159, 83, 0.25);
    border-radius: 6px;
    padding: 6px 10px;
    font-size: 13px;
    cursor: pointer;
    transition: border-color 0.15s ease;
}

.experiments-toolbar__select:hover,
.experiments-toolbar__select:focus {
    border-color: rgba(192, 159, 83, 0.55);
    outline: none;
}

.experiments-toolbar__view {
    display: inline-flex;
    border: 1px solid rgba(192, 159, 83, 0.25);
    border-radius: 6px;
    overflow: hidden;
}

.experiments-toolbar__view-btn {
    appearance: none;
    background: rgba(34, 34, 40, 0.6);
    color: #c4c4c4;
    border: none;
    padding: 6px 14px;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.02em;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease;
}

.experiments-toolbar__view-btn:not(:last-child) {
    border-right: 1px solid rgba(192, 159, 83, 0.25);
}

.experiments-toolbar__view-btn.is-active {
    background: rgba(192, 159, 83, 0.22);
    color: #f5d27a;
}

.experiments-toolbar__view-btn:not(.is-active):hover {
    background: rgba(192, 159, 83, 0.1);
    color: #ececec;
}

/* ---------------------------------------------------------------- */
/* Lift chip + confidence badge on variant cards                    */
/* ---------------------------------------------------------------- */

.experiment-card__control-badge {
    display: inline-flex;
    align-items: center;
    padding: 3px 9px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    background: rgba(96, 125, 139, 0.22);
    color: #c2d1d9;
    border: 1px solid rgba(96, 125, 139, 0.45);
}

.experiment-card__lift-row {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 6px;
}

.experiment-card__lift {
    display: inline-flex;
    align-items: center;
    padding: 4px 10px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.01em;
}

.experiment-card__lift--up {
    background: rgba(76, 175, 80, 0.18);
    color: #8de08e;
    border: 1px solid rgba(76, 175, 80, 0.4);
}

.experiment-card__lift--down {
    background: rgba(244, 67, 54, 0.18);
    color: #ff8a80;
    border: 1px solid rgba(244, 67, 54, 0.4);
}

.experiment-card__lift--flat {
    background: rgba(158, 158, 158, 0.18);
    color: #c4c4c4;
    border: 1px solid rgba(158, 158, 158, 0.35);
}

.experiment-card__confidence {
    display: inline-flex;
    align-items: center;
    padding: 3px 9px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.02em;
}

.experiment-card__confidence--win {
    background: rgba(76, 175, 80, 0.14);
    color: #8de08e;
    border: 1px solid rgba(76, 175, 80, 0.3);
}

.experiment-card__confidence--loss {
    background: rgba(244, 67, 54, 0.14);
    color: #ff8a80;
    border: 1px solid rgba(244, 67, 54, 0.3);
}

.experiment-card__confidence--warn {
    background: rgba(255, 152, 0, 0.14);
    color: #ffc97a;
    border: 1px solid rgba(255, 152, 0, 0.3);
}

.experiment-card__confidence--soft {
    background: rgba(120, 144, 156, 0.18);
    color: #b0bec5;
    border: 1px solid rgba(120, 144, 156, 0.32);
}

.experiment-card__confidence--neutral {
    background: rgba(158, 158, 158, 0.14);
    color: #c4c4c4;
    border: 1px solid rgba(158, 158, 158, 0.3);
}

/* ---------------------------------------------------------------- */
/* Compact table view                                               */
/* ---------------------------------------------------------------- */

.experiments-compact {
    overflow-x: auto;
    background: rgba(22, 22, 26, 0.55);
    border: 1px solid rgba(192, 159, 83, 0.14);
    border-radius: 10px;
    padding: 4px;
}

.experiments-compact__table {
    width: 100%;
    border-collapse: collapse;
    color: #ececec;
    font-size: 13px;
    min-width: 760px;
}

.experiments-compact__table thead th {
    text-align: left;
    padding: 10px 12px;
    font-weight: 600;
    font-size: 11px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(192, 159, 83, 0.85);
    border-bottom: 1px solid rgba(192, 159, 83, 0.18);
    white-space: nowrap;
}

.experiments-compact__table tbody td {
    padding: 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    vertical-align: middle;
}

.experiments-compact__table tbody tr:last-child td {
    border-bottom: none;
}

.experiments-compact__table tbody tr:hover {
    background: rgba(192, 159, 83, 0.06);
}

.experiments-compact__num {
    text-align: right;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}

.experiments-compact__variant-name {
    font-weight: 600;
    color: #f3f3f3;
}

.experiments-compact__tag {
    display: inline-block;
    margin-left: 8px;
    padding: 2px 8px;
    border-radius: 999px;
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 600;
    background: rgba(96, 125, 139, 0.22);
    color: #c2d1d9;
    border: 1px solid rgba(96, 125, 139, 0.4);
}

.experiments-compact__tag--winning {
    background: rgba(192, 159, 83, 0.22);
    color: #f5d27a;
    border-color: rgba(192, 159, 83, 0.5);
}

.experiments-compact__row--control td {
    background: rgba(96, 125, 139, 0.06);
}

.experiments-compact__row--winning td {
    background: rgba(192, 159, 83, 0.07);
}

.experiments-compact__sig {
    display: inline-flex;
    align-items: center;
    padding: 3px 9px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.02em;
    background: rgba(158, 158, 158, 0.14);
    color: #c4c4c4;
    border: 1px solid rgba(158, 158, 158, 0.3);
    white-space: nowrap;
}

.experiments-compact__sig--win {
    background: rgba(76, 175, 80, 0.18);
    color: #8de08e;
    border-color: rgba(76, 175, 80, 0.4);
}

.experiments-compact__sig--loss {
    background: rgba(244, 67, 54, 0.18);
    color: #ff8a80;
    border-color: rgba(244, 67, 54, 0.4);
}

.experiments-compact__sig--warn {
    background: rgba(255, 152, 0, 0.18);
    color: #ffc97a;
    border-color: rgba(255, 152, 0, 0.4);
}

.experiments-compact__sig--soft {
    background: rgba(120, 144, 156, 0.18);
    color: #b0bec5;
    border-color: rgba(120, 144, 156, 0.32);
}

.experiments-compact__sig--control {
    background: rgba(96, 125, 139, 0.22);
    color: #c2d1d9;
    border-color: rgba(96, 125, 139, 0.4);
}

/* ---------------------------------------------------------------- */
/* Experiments list view — domain-scoped summary cards              */
/* ---------------------------------------------------------------- */

.experiments-list-intro-block {
    flex: 1 1 320px;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.experiments-list-domain-pill {
    display: inline-flex;
    align-self: flex-start;
    align-items: center;
    padding: 3px 10px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    background: rgba(192, 159, 83, 0.16);
    color: #f5d27a;
    border: 1px solid rgba(192, 159, 83, 0.35);
}

.experiments-list-empty {
    background: rgba(22, 22, 26, 0.55);
    border: 1px dashed rgba(192, 159, 83, 0.25);
    border-radius: 12px;
    padding: 32px 28px;
    text-align: center;
    margin-top: 8px;
}

.experiments-list-empty__title {
    font-size: 16px;
    font-weight: 600;
    color: #f3f3f3;
    margin: 0 0 6px;
}

.experiments-list-empty__sub {
    font-size: 13px;
    color: #a4a4a8;
    margin: 0;
    line-height: 1.55;
}

.experiments-list-empty__sub code {
    background: rgba(192, 159, 83, 0.12);
    color: #f5d27a;
    padding: 2px 6px;
    border-radius: 4px;
    font-size: 12px;
}

.experiments-list-grid {
    list-style: none;
    padding: 0;
    margin: 8px 0 0;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 14px;
}

.experiments-list-card-wrap {
    list-style: none;
}

.experiments-list-card {
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding: 18px 20px;
    background: rgba(22, 22, 26, 0.6);
    border: 1px solid rgba(192, 159, 83, 0.18);
    border-radius: 12px;
    text-decoration: none;
    color: inherit;
    transition: border-color 0.15s ease, transform 0.15s ease,
        background 0.15s ease;
    height: 100%;
}

.experiments-list-card:hover,
.experiments-list-card:focus-visible {
    border-color: rgba(192, 159, 83, 0.5);
    background: rgba(34, 34, 40, 0.85);
    transform: translateY(-1px);
    outline: none;
}

.experiments-list-card__header {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.experiments-list-card__title {
    margin: 0;
    font-size: 16px;
    font-weight: 700;
    color: #f3f3f3;
    letter-spacing: -0.01em;
    word-break: break-word;
}

.experiments-list-card__chips {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.experiments-list-card__chip {
    display: inline-flex;
    align-items: center;
    padding: 3px 9px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.02em;
    background: rgba(96, 125, 139, 0.18);
    color: #c2d1d9;
    border: 1px solid rgba(96, 125, 139, 0.35);
}

.experiments-list-card__chip--channel {
    background: rgba(192, 159, 83, 0.16);
    color: #f5d27a;
    border-color: rgba(192, 159, 83, 0.4);
}

.experiments-list-card__chip--mixed {
    background: rgba(120, 144, 156, 0.18);
    color: #b0bec5;
    border-color: rgba(120, 144, 156, 0.35);
}

.experiments-list-card__chip--untargeted {
    background: rgba(158, 158, 158, 0.14);
    color: #c4c4c4;
    border-color: rgba(158, 158, 158, 0.3);
}

.experiments-list-card__chip--domain {
    background: rgba(34, 34, 40, 0.95);
    color: #ececec;
    border-color: rgba(255, 255, 255, 0.12);
}

.experiments-list-card__metrics {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
    gap: 10px 14px;
    margin: 0;
}

.experiments-list-card__metrics > div {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}

.experiments-list-card__metrics dt {
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(192, 159, 83, 0.85);
    font-weight: 600;
}

.experiments-list-card__metrics dd {
    margin: 0;
    font-size: 15px;
    font-weight: 700;
    color: #f3f3f3;
    line-height: 1.2;
    font-variant-numeric: tabular-nums;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.experiments-list-card__leader {
    display: inline-flex;
    align-items: baseline;
    gap: 6px;
}

.experiments-list-card__leader-rate {
    font-size: 11px;
    color: #8de08e;
    font-weight: 600;
}

.experiments-list-card__cta {
    margin-top: auto;
    align-self: flex-start;
    font-size: 12px;
    font-weight: 600;
    color: rgba(192, 159, 83, 0.9);
