.dashboard-content {
    width: 100%;
    max-width: 1480px;
    margin: 0 auto;
    flex: 1;
    padding: 0 20px;
}

.activeDomain {
    color: aliceblue;
    text-decoration: none;
    text-transform: uppercase;
}

.user {
    padding: 20px;
    background-color: #fff;
    color: #3d3d3d;
    border-radius: 10px;
}

.profile-user {
    font-size: 30px;
}

.profilePicture-container {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin-bottom: 30px;
    background-color: #464646;
    padding: 30px;
    border-radius: 10px;
}

.profilePicture {
    width: 190px;
    height: 190px;
    border-radius: 50%;
    object-fit: cover;
}

.warning{
    margin-right: 10px;
    font-weight: bold;
}

.warning.critical{
    color: red;
}

.warning.high{
    color: orange;
}

.warning.high::before{
    content: "!!";
    margin-right: 5px;
    font-weight: bold;
}

.warning.critical::before {
    content: "!!!";
    margin-right: 5px;
    font-weight: bold;
}

.warning.medium{
    color: yellow;
}
.warning.low{
    color: green;
}

.grid-7 .span-2 {
    grid-column: span 2;
    min-width: 0;
}

.dashboard-marketing-teaser {
    margin: 0 0 16px;
    padding: 10px 14px;
    font-size: 0.9rem;
    line-height: 1.45;
    color: #2a2a2a;
    background: linear-gradient(105deg, #f6f1e8 0%, #f0ebe3 100%);
    border: 1px solid rgba(163, 133, 64, 0.35);
    border-radius: 8px;
}

.dashboard-marketing-teaser p {
    margin: 0;
}

.dashboard-marketing-teaser a {
    font-weight: 600;
    color: #a38540;
    text-decoration: none;
    white-space: nowrap;
}

.dashboard-marketing-teaser a:hover {
    text-decoration: underline;
}

/* ── Dashboard section wrapper ── */
.dashboard-section {
    padding-top: 36px;
}

.dashboard-section-label {
    margin: 0 0 16px;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.28);
}

/* ── Hero KPI row (acceptance + essential-only) ── */
.dashboard-hero-kpis {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 12px;
}

.dashboard-hero-kpis .small-widget-number {
    font-size: clamp(2rem, 3.5vw, 2.8rem);
    font-weight: 300;
    letter-spacing: -0.02em;
}

.dashboard-hero-kpis .key-highlight-widget {
    padding: 20px 22px 18px;
}

.dashboard-hero-kpis--loading {
    min-height: 110px;
}

/* ── EU / Non-EU geo stats strip (below map) ── */
.dashboard-geo-stats {
    display: flex;
    align-items: center;
    gap: 0;
    margin-top: 12px;
    padding: 14px 18px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(0, 0, 0, 0.18);
}

.dashboard-geo-stat {
    display: flex;
    align-items: baseline;
    gap: 8px;
    flex: 1;
    min-width: 0;
}

.dashboard-geo-stat__value {
    font-size: 1.1rem;
    font-weight: 600;
    color: #e8e8e8;
    font-variant-numeric: tabular-nums;
    flex-shrink: 0;
}

.dashboard-geo-stat__label {
    font-size: 0.78rem;
    color: rgba(255, 255, 255, 0.35);
    font-weight: 500;
    flex-shrink: 0;
}

.dashboard-geo-stat__rate {
    font-size: 0.75rem;
    color: #c0a053;
    font-weight: 500;
    flex-shrink: 0;
}

.dashboard-geo-stat__divider {
    width: 1px;
    height: 28px;
    background: rgba(255, 255, 255, 0.08);
    flex-shrink: 0;
    margin: 0 20px;
}


/* ── Decision behaviour inline KPI tile ── */
.dashboard-behaviour-kpi {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 14px 18px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(0, 0, 0, 0.18);
}

.dashboard-behaviour-kpi__content {
    display: flex;
    align-items: baseline;
    gap: 10px;
    min-width: 0;
    flex-wrap: wrap;
}

.dashboard-behaviour-kpi__label {
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.32);
    font-weight: 500;
    flex-shrink: 0;
}

.dashboard-behaviour-kpi__value {
    font-size: 1.25rem;
    font-weight: 600;
    color: #e8e8e8;
    font-variant-numeric: tabular-nums;
    flex-shrink: 0;
}

.dashboard-behaviour-kpi__sub {
    font-size: 0.72rem;
    color: rgba(255, 255, 255, 0.22);
    flex-shrink: 0;
}

.dashboard-behaviour-kpi__btn {
    flex-shrink: 0;
    padding: 7px 14px;
    border-radius: 7px;
    border: 1px solid rgba(192, 159, 83, 0.3);
    background: rgba(192, 159, 83, 0.07);
    color: #c0a053;
    font-size: 0.78rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease;
    letter-spacing: 0.01em;
}

.dashboard-behaviour-kpi__btn:hover {
    background: rgba(192, 159, 83, 0.14);
    border-color: rgba(192, 159, 83, 0.5);
}

/* ── Compliance / quick-link rows ── */
.dashboard-compliance-links {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.dashboard-compliance-link {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-radius: 9px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(0, 0, 0, 0.15);
    text-decoration: none;
    transition: border-color 0.15s ease, background 0.15s ease;
}

.dashboard-compliance-link:hover {
    border-color: rgba(192, 159, 83, 0.3);
    background: rgba(192, 159, 83, 0.05);
    text-decoration: none;
}

.dashboard-compliance-link__label {
    font-size: 0.85rem;
    font-weight: 500;
    color: rgba(255, 255, 255, 0.65);
}

.dashboard-compliance-link:hover .dashboard-compliance-link__label {
    color: #e8e8e8;
}

.dashboard-compliance-link__arrow {
    font-size: 0.85rem;
    color: rgba(192, 159, 83, 0.6);
    flex-shrink: 0;
    transition: transform 0.15s ease, color 0.15s ease;
}

.dashboard-compliance-link:hover .dashboard-compliance-link__arrow {
    transform: translateX(3px);
    color: #c0a053;
}

/* ── Marketing link (replaces teaser section) ── */
.dashboard-marketing-link {
    margin: 16px 0 0;
    font-size: 0.8125rem;
    color: #666;
}

.dashboard-marketing-link a {
    color: #a38540;
    font-weight: 600;
    text-decoration: none;
}

.dashboard-marketing-link a:hover {
    text-decoration: underline;
}

/* Workspace active banner */
.dashboard-workspace-banner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
    margin-bottom: 16px;
    padding: 12px 18px;
    border-radius: 10px;
    border: 1px solid rgba(192, 159, 83, 0.35);
    background: linear-gradient(105deg, rgba(192, 159, 83, 0.1) 0%, rgba(0, 0, 0, 0.2) 100%);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.dashboard-workspace-banner__left {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.dashboard-workspace-banner__kicker {
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #c0a053;
    flex-shrink: 0;
}

.dashboard-workspace-banner__name {
    font-size: 0.9rem;
    font-weight: 600;
    color: #f0e6d4;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.dashboard-workspace-banner__domains {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
}

.dashboard-workspace-banner__domain-tag {
    display: inline-block;
    padding: 3px 9px;
    border-radius: 20px;
    border: 1px solid rgba(192, 159, 83, 0.25);
    background: rgba(192, 159, 83, 0.08);
    font-size: 0.72rem;
    font-weight: 500;
    color: #c0a053;
    white-space: nowrap;
}

.dashboard-workspace-banner__domain-tag--more {
    color: rgba(192, 159, 83, 0.6);
    border-style: dashed;
}

/* Domain Verification Warning Banner */
.dashboard-verification-warning {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 20px;
    padding: 14px 18px;
    border-radius: 12px;
    background: rgba(220, 160, 60, 0.1);
    border: 1px solid rgba(220, 160, 60, 0.3);
}

.dashboard-verification-warning--expired {
    background: rgba(220, 100, 80, 0.1);
    border-color: rgba(220, 100, 80, 0.3);
}

.dashboard-verification-warning__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    flex-shrink: 0;
    border-radius: 50%;
    background: rgba(220, 160, 60, 0.2);
    border: 1px solid rgba(220, 160, 60, 0.4);
    color: #e8c76a;
    font-size: 1.25rem;
    font-weight: 700;
}

.dashboard-verification-warning--expired .dashboard-verification-warning__icon {
    background: rgba(220, 100, 80, 0.2);
    border-color: rgba(220, 100, 80, 0.4);
    color: #f0a8a0;
}

.dashboard-verification-warning__content {
    flex: 1;
    min-width: 0;
}

.dashboard-verification-warning__content strong {
    display: block;
    font-size: 0.875rem;
    font-weight: 600;
    color: #e8c76a;
    margin-bottom: 4px;
}

.dashboard-verification-warning--expired .dashboard-verification-warning__content strong {
    color: #f0a8a0;
}

.dashboard-verification-warning__content p {
    margin: 0;
    font-size: 0.8125rem;
    color: rgba(197, 197, 197, 0.85);
    line-height: 1.45;
}

.dashboard-verification-warning__action {
    flex-shrink: 0;
    padding: 8px 16px;
    border-radius: 8px;
    background: rgba(220, 160, 60, 0.15);
    border: 1px solid rgba(220, 160, 60, 0.35);
    color: #e8c76a;
    font-size: 0.8125rem;
    font-weight: 600;
    text-decoration: none;
    transition: background 0.2s ease, border-color 0.2s ease;
}

.dashboard-verification-warning__action:hover {
    background: rgba(220, 160, 60, 0.25);
    border-color: rgba(220, 160, 60, 0.5);
    text-decoration: none;
}

.dashboard-verification-warning--expired .dashboard-verification-warning__action {
    background: rgba(220, 100, 80, 0.15);
    border-color: rgba(220, 100, 80, 0.35);
    color: #f0a8a0;
}

.dashboard-verification-warning--expired .dashboard-verification-warning__action:hover {
    background: rgba(220, 100, 80, 0.25);
    border-color: rgba(220, 100, 80, 0.5);
}

@media screen and (max-width: 900px) {
    .dashboard-content {
        padding: 0 20px;
    }

    .grid-3-4 {
        grid-template-columns: 1fr;
    }

    .topWidget{
        display: flex;
        overflow-x: auto;
        justify-content: flex-start;
    }

    .topWidget > * {
        flex: 0 0 auto;
    }

