/* ========== World map layout (dashboard) ========== */

.world-map {
    display: grid;
    grid-template-columns: 1fr minmax(260px, 300px);
    gap: 20px;
    align-items: stretch;
    width: 100%;
    min-height: 0;
}

.world-map--empty {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 200px;
    padding: 32px;
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(0, 0, 0, 0.2);
}

.world-map__empty-msg {
    margin: 0;
    font-size: 0.95rem;
    color: rgba(255, 255, 255, 0.45);
    text-align: center;
}

.world-map__main {
    display: flex;
    flex-direction: column;
    min-width: 0;
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: linear-gradient(
        165deg,
        rgba(52, 52, 52, 0.5) 0%,
        rgba(34, 34, 34, 0.65) 100%
    );
    box-shadow: 0 8px 28px rgba(0, 0, 0, 0.22);
    overflow: hidden;
}

.world-map__main::before {
    content: "";
    display: block;
    height: 3px;
    background: linear-gradient(
        90deg,
        rgba(192, 159, 83, 0.25),
        rgba(192, 159, 83, 0.85),
        rgba(192, 159, 83, 0.25)
    );
}

.world-map__header {
    padding: 16px 20px 12px;
    text-align: left;
}

.world-map__title {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 600;
    color: rgb(240, 240, 240);
    letter-spacing: -0.02em;
}

.world-map__subtitle {
    margin: 6px 0 0 0;
    font-size: 0.8rem;
    line-height: 1.45;
    color: rgba(255, 255, 255, 0.42);
    max-width: 42rem;
}

.world-map__map-shell {
    flex: 1;
    min-height: 360px;
    padding: 0 8px 12px;
}

.world-map__map-inner {
    width: 100%;
    height: 100%;
    min-height: 340px;
    border-radius: 10px;
    overflow: hidden;
    background: rgba(0, 0, 0, 0.12);
}

.world-map__side {
    display: flex;
    flex-direction: column;
    min-width: 0;
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: linear-gradient(180deg, rgba(48, 48, 48, 0.75) 0%, rgba(32, 32, 32, 0.9) 100%);
    box-shadow: 0 8px 28px rgba(0, 0, 0, 0.2);
    overflow: hidden;
}

.world-map__side-head {
    padding: 14px 16px 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.world-map__side-title {
    margin: 0;
    font-size: 0.82rem;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.5);
}

.world-map__side-hint {
    margin: 6px 0 0 0;
    font-size: 0.72rem;
    color: rgba(255, 255, 255, 0.35);
}

.world-map__list-scroll {
    flex: 1;
    overflow-y: auto;
    padding: 8px 10px 12px;
    min-height: 200px;
    max-height: 420px;
}

.world-map__row {
    display: flex;
    align-items: stretch;
    gap: 10px;
    width: 100%;
    margin: 0 0 8px 0;
    padding: 8px 10px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 10px;
    background: rgba(0, 0, 0, 0.18);
    color: inherit;
    font: inherit;
    text-align: left;
    cursor: pointer;
    transition: border-color 0.2s ease, background 0.2s ease;
}

.world-map__row:hover:not(:disabled) {
    border-color: rgba(192, 159, 83, 0.35);
    background: rgba(192, 159, 83, 0.06);
}

.world-map__row:disabled {
    opacity: 0.45;
    cursor: default;
}

.world-map__row:focus-visible {
    outline: 2px solid rgba(192, 159, 83, 0.7);
    outline-offset: 2px;
}

.world-map__row-rank {
    flex-shrink: 0;
    width: 26px;
    height: 26px;
    margin-top: 2px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.72rem;
    font-weight: 700;
    color: rgba(255, 255, 255, 0.5);
    background: rgba(255, 255, 255, 0.06);
    border-radius: 8px;
}

.world-map__row-body {
    flex: 1;
    min-width: 0;
}

.world-map__row-top {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 8px;
}

.world-map__row-name {
    font-size: 0.85rem;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.9);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.world-map__row-val {
    flex-shrink: 0;
    font-size: 0.82rem;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    color: rgba(192, 159, 83, 0.95);
    text-align: right;
}

.world-map__row-cmp {
    display: inline-block;
    margin-left: 6px;
    font-size: 0.68rem;
    font-weight: 600;
    color: rgba(140, 200, 235, 0.92);
    vertical-align: middle;
}

.world-map__row-bar {
    margin-top: 6px;
    height: 4px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.08);
    overflow: hidden;
}

.world-map__row-bar-fill {
    height: 100%;
    border-radius: 999px;
    background: linear-gradient(90deg, rgba(192, 159, 83, 0.35), rgba(218, 190, 120, 0.95));
    transition: width 0.35s ease;
}

@media screen and (max-width: 960px) {
    .world-map {
        grid-template-columns: 1fr;
    }

    .world-map__list-scroll {
        max-height: 260px;
    }

    .world-map__map-shell {
        min-height: 300px;
    }

    .world-map__map-inner {
        min-height: 280px;
    }
}

/* ========== Country detail drawer ========== */

.world-map-drawer-backdrop {
    position: fixed;
    inset: 0;
    z-index: 198;
    background: rgba(0, 0, 0, 0.55);
    animation: world-map-fade-in 0.2s ease;
}

.world-map-drawer {
    position: fixed;
    top: 0;
    right: 0;
    z-index: 199;
    width: min(420px, 100vw - 16px);
    max-width: 100%;
    height: 100vh;
    height: 100dvh;
    display: flex;
    flex-direction: column;
    padding: 0;
    margin: 0;
    border: none;
    border-left: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px 0 0 14px;
    background: linear-gradient(180deg, rgba(44, 44, 44, 0.98) 0%, rgba(26, 26, 26, 1) 100%);
    box-shadow: -12px 0 48px rgba(0, 0, 0, 0.45);
    animation: world-map-slide-in 0.28s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}

@keyframes world-map-fade-in {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

@keyframes world-map-slide-in {
    from {
        transform: translateX(100%);
        opacity: 0.85;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

.world-map-drawer__header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    padding: 18px 18px 14px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    flex-shrink: 0;
}

.world-map-drawer__title-wrap {
    min-width: 0;
}

.world-map-drawer__title {
    margin: 0;
    font-size: 1.2rem;
    font-weight: 600;
    color: rgb(245, 245, 245);
    line-height: 1.25;
    word-break: break-word;
}

.world-map-drawer__iso {
    display: inline-block;
    margin-top: 6px;
    padding: 2px 8px;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    color: rgba(255, 255, 255, 0.45);
    background: rgba(255, 255, 255, 0.06);
    border-radius: 6px;
}

.world-map-drawer__close {
    flex-shrink: 0;
    width: 40px;
    height: 40px;
    margin: 0;
    padding: 0;
    border: none;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.06);
    color: rgba(255, 255, 255, 0.85);
    font-size: 26px;
    line-height: 1;
    cursor: pointer;
    transition: background 0.2s ease;
}

.world-map-drawer__close:hover {
    background: rgba(255, 255, 255, 0.12);
}

.world-map-drawer__share {
    padding: 14px 18px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    flex-shrink: 0;
}

.world-map-drawer__share-label {
    display: block;
    font-size: 0.62rem;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.38);
    margin-bottom: 8px;
}

.world-map-drawer__share-bar {
    height: 8px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.08);
    overflow: hidden;
}

.world-map-drawer__share-fill {
    height: 100%;
    border-radius: 999px;
    background: linear-gradient(90deg, rgba(192, 159, 83, 0.4), rgba(218, 190, 120, 0.95));
    transition: width 0.4s ease;
}

.world-map-drawer__share-pct {
    display: block;
    margin-top: 6px;
    font-size: 0.8rem;
    font-weight: 600;
    color: rgba(192, 159, 83, 0.9);
    font-variant-numeric: tabular-nums;
}

.world-map-drawer__empty {
    margin: 0;
    padding: 20px 18px;
    font-size: 0.88rem;
    line-height: 1.5;
    color: rgba(255, 255, 255, 0.45);
}

.world-map-drawer__stats {
    list-style: none;
    margin: 0;
    padding: 12px 18px 20px;
    overflow-y: auto;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.world-map-drawer__stat {
    padding: 12px 14px;
    border-radius: 10px;
    background: rgba(0, 0, 0, 0.22);
    border: 1px solid rgba(255, 255, 255, 0.06);
}

.world-map-drawer__stat-top {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
}

.world-map-drawer__stat-label {
    font-size: 0.68rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.4);
}

.world-map-drawer__stat-value {
    font-size: 1rem;
    font-weight: 700;
    font-variant-numeric: tabular-nums;
    color: rgb(240, 240, 240);
    flex-shrink: 0;
}

.world-map-drawer__stat-sub {
    display: block;
    margin-top: 6px;
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.45);
    font-variant-numeric: tabular-nums;
}

.world-map-drawer__stat-cmp {
    display: block;
    margin-top: 6px;
    font-size: 0.72rem;
    line-height: 1.4;
    color: rgba(150, 200, 235, 0.9);
    font-variant-numeric: tabular-nums;
}

.world-map-drawer__extras {
    flex-shrink: 0;
    padding: 0 18px 22px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    max-height: min(55vh, 480px);
    overflow-y: auto;
}

.world-map-drawer__extras-title {
    margin: 0;
    padding: 16px 0 10px;
    font-size: 0.65rem;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.38);
}

.world-map-drawer__embed {
    border-radius: 12px;
    overflow: hidden;
}

.world-map-drawer__embed .device-interactions {
    margin: 0;
    box-shadow: none;
}

.world-map-drawer__embed .device-interactions::before {
    height: 2px;
}

.world-map-drawer__cta {
    flex-shrink: 0;
    padding: 14px 18px 18px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.world-map-drawer__cta-link {
    position: relative;
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-rows: auto auto;
    gap: 2px 12px;
    align-items: center;
    padding: 12px 14px;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(192, 159, 83, 0.18), rgba(192, 159, 83, 0.06));
    border: 1px solid rgba(192, 159, 83, 0.35);
    color: #f5e6c5;
    text-decoration: none;
    transition: background 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.world-map-drawer__cta-link:hover,
.world-map-drawer__cta-link:focus-visible {
    background: linear-gradient(135deg, rgba(192, 159, 83, 0.28), rgba(192, 159, 83, 0.1));
    border-color: rgba(192, 159, 83, 0.6);
    transform: translateY(-1px);
    outline: none;
}

.world-map-drawer__cta-label {
    grid-column: 1;
    grid-row: 1;
    font-size: 0.9rem;
    font-weight: 600;
    color: #fff;
    letter-spacing: 0.01em;
}

.world-map-drawer__cta-sub {
    grid-column: 1;
    grid-row: 2;
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.62);
    line-height: 1.35;
}

.world-map-drawer__cta-arrow {
    grid-column: 2;
    grid-row: 1 / span 2;
    font-size: 1.15rem;
    font-weight: 600;
    color: #c09f53;
}

@media screen and (max-width: 480px) {
    .world-map-drawer {
        width: 100vw;
        border-radius: 0;
