___CSS_LOADER_EXPORT___.push([module.id, `/* ── Hero map — full-width ── */
.compliance-hero {
    position: relative;
    width: 100%;
    min-height: 380px;
    max-height: 520px;
    height: 46vh;
    overflow: hidden;
    background: #0e0c09;
}

/* Bottom fade to page background */
.compliance-hero::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 200px;
    background: linear-gradient(to bottom, transparent 0%, rgba(14, 12, 9, 0.85) 65%, #0e0c09 100%);
    pointer-events: none;
    z-index: 2;
}

/* Suppress the right-side country list — map fills full width in the hero */
.compliance-hero .world-map {
    grid-template-columns: 1fr;
    height: 100%;
    min-height: 0;
}

.compliance-hero .world-map__side {
    display: none;
}

.compliance-hero .world-map__main {
    height: 100%;
}

.compliance-hero .world-map__header {
    display: none;
}

.compliance-hero .world-map__map-shell {
    height: 100%;
    flex: 1;
}

.compliance-hero .svgMap-map-wrapper {
    min-height: 0;
    height: 100%;
}

/* Stats strip overlaid at the bottom of the hero, above the gradient */
.compliance-hero__stats {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    z-index: 3;
    display: flex;
    align-items: center;
    gap: 0;
    padding: 16px 24px 20px;
}

.compliance-hero__stat {
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex: 0 0 auto;
}

.compliance-hero__stat-value {
    font-size: 1.4rem;
    font-weight: 300;
    color: #e8e8e8;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.02em;
    line-height: 1.1;
}

.compliance-hero__stat-label {
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.3);
}

.compliance-hero__stat-divider {
    width: 1px;
    height: 32px;
    background: rgba(255, 255, 255, 0.08);
    flex-shrink: 0;
    margin: 0 22px;
}

.compliance-hero__audit-btn {
    margin-left: auto;
    flex-shrink: 0;
    padding: 9px 18px;
    border-radius: 8px;
    border: 1px solid rgba(192, 159, 83, 0.4);
    background: rgba(192, 159, 83, 0.1);
    color: #c0a053;
    font-size: 0.82rem;
    font-weight: 600;
    text-decoration: none;
    letter-spacing: 0.02em;
    backdrop-filter: blur(8px);
    transition: background 0.15s ease, border-color 0.15s ease;
}

.compliance-hero__audit-btn:hover {
    background: rgba(192, 159, 83, 0.2);
    border-color: rgba(192, 159, 83, 0.6);
    text-decoration: none;
}

/* ── Content area below hero ── */
.compliance-page {
    padding-top: 20px;
}

/* ── Pre-consent data transfer section ── */
.compliance-transfers__card {
    padding: 20px 22px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.07);
    background: rgba(24, 22, 18, 0.75);
}

.compliance-transfers__header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 20px;
}

.compliance-transfers__header-text {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
}

.compliance-transfers__desc {
    margin: 0;
    font-size: 0.8rem;
    line-height: 1.5;
    color: rgba(255, 255, 255, 0.38);
    max-width: 520px;
}

.compliance-transfers__scan-time {
    font-size: 0.67rem;
    color: rgba(255, 255, 255, 0.22);
    font-weight: 500;
}

.compliance-transfers__scan-btn {
    flex-shrink: 0;
    padding: 8px 16px;
    border-radius: 8px;
    border: 1px solid rgba(192, 159, 83, 0.35);
    background: rgba(192, 159, 83, 0.08);
    color: #c0a053;
    font-size: 0.78rem;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    letter-spacing: 0.02em;
    transition: background 0.15s ease, border-color 0.15s ease, opacity 0.15s ease;
}

.compliance-transfers__scan-btn:hover:not(:disabled) {
    background: rgba(192, 159, 83, 0.16);
    border-color: rgba(192, 159, 83, 0.55);
}

.compliance-transfers__scan-btn.--loading,
.compliance-transfers__scan-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Empty / status states */
.compliance-transfers__empty {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 18px 0 4px;
    font-size: 0.82rem;
    color: rgba(255, 255, 255, 0.3);
}

.compliance-transfers__empty-icon {
    font-size: 1.1rem;
    line-height: 1;
    flex-shrink: 0;
}

.compliance-transfers__empty--loading {
    color: rgba(192, 159, 83, 0.55);
}

.compliance-transfers__empty--clean {
    color: rgba(120, 200, 140, 0.7);
}

/* Transfer rows */
.compliance-transfers__list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.compliance-transfers__row {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    border-radius: 8px;
    border: 1px solid rgba(255, 80, 80, 0.15);
    background: rgba(255, 60, 60, 0.05);
}

.compliance-transfers__row-main {
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex: 1;
    min-width: 0;
}

.compliance-transfers__row-service {
    font-size: 0.88rem;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.82);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.compliance-transfers__row-host {
    font-size: 0.7rem;
    color: rgba(255, 255, 255, 0.3);
    font-family: monospace;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Category badge */
.compliance-transfers__row-cat {
    flex-shrink: 0;
    padding: 3px 9px;
    border-radius: 20px;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border: 1px solid transparent;
}

.compliance-transfers__row-cat--advertising {
    background: rgba(220, 80, 80, 0.12);
    border-color: rgba(220, 80, 80, 0.3);
    color: rgba(240, 140, 130, 0.9);
}

.compliance-transfers__row-cat--analytics {
    background: rgba(100, 160, 220, 0.1);
    border-color: rgba(100, 160, 220, 0.25);
    color: rgba(140, 190, 240, 0.85);
}

.compliance-transfers__row-cat--social {
    background: rgba(130, 100, 200, 0.1);
    border-color: rgba(130, 100, 200, 0.25);
    color: rgba(175, 150, 230, 0.85);
}

.compliance-transfers__row-cat--other,
.compliance-transfers__row-cat--unknown {
    background: rgba(255, 255, 255, 0.04);
    border-color: rgba(255, 255, 255, 0.1);
    color: rgba(255, 255, 255, 0.35);
}

/* Pre-consent flag */
.compliance-transfers__row-flag {
    flex-shrink: 0;
    padding: 3px 9px;
    border-radius: 20px;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    background: rgba(220, 100, 60, 0.12);
    border: 1px solid rgba(220, 100, 60, 0.3);
    color: rgba(240, 160, 120, 0.9);
}

@media (max-width: 580px) {
    .compliance-transfers__header {
        flex-direction: column;
        align-items: stretch;
    }

    .compliance-transfers__scan-btn {
        align-self: flex-start;
    }

    .compliance-transfers__row {
        flex-wrap: wrap;
    }
}

.compliance-page__audit {
    margin-top: 32px;
}

.compliance-page__audit .audit-snapshot-card:hover {
    transform: none;
    border-color: rgba(255, 255, 255, 0.1);
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.16);
}

@media (max-width: 680px) {
    .compliance-hero {
        max-height: 60vw;
        min-height: 240px;
    }

    .compliance-hero__stats {
        flex-wrap: wrap;
        gap: 10px 0;
        padding: 12px 16px 16px;
    }

    .compliance-hero__stat-divider {
        display: none;
    }

    .compliance-hero__audit-btn {
        margin-left: 0;
        width: 100%;
        text-align: center;
    }
}

/* ── Category summary cards ─────────────────────────────────────────────────── */
.transfers-summary {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 18px;
}

.transfers-summary__card {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    padding: 12px 18px 10px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.07);
    background: rgba(255, 255, 255, 0.02);
    cursor: pointer;
    font-family: inherit;
    color: inherit;
    transition: background 0.15s ease, border-color 0.15s ease;
    min-width: 76px;
    text-align: center;
}

.transfers-summary__card:hover {
    background: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.13);
}

.transfers-summary__card.--active {
    background: color-mix(in srgb, var(--cat-color, #c0a053) 12%, transparent);
    border-color: color-mix(in srgb, var(--cat-color, #c0a053) 40%, transparent);
}

.transfers-summary__card-icon {
    font-size: 0.9rem;
    line-height: 1;
    color: var(--cat-color, rgba(255, 255, 255, 0.5));
}

.transfers-summary__card-count {
    font-size: 1.6rem;
    font-weight: 200;
    color: rgba(255, 255, 255, 0.88);
    line-height: 1;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.02em;
}

.transfers-summary__card-label {
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.35);
}

.transfers-summary__card-risk {
    font-size: 0.58rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    padding: 2px 7px;
    border-radius: 10px;
    margin-top: 2px;
}

.transfers-summary__card-risk.--high {
    background: rgba(220, 80, 80, 0.15);
    color: rgba(240, 130, 120, 0.9);
}

.transfers-summary__card-risk.--medium {
    background: rgba(220, 160, 60, 0.12);
    color: rgba(230, 180, 100, 0.85);
}

.transfers-summary__card-risk.--low {
    background: rgba(80, 168, 120, 0.1);
    color: rgba(120, 200, 150, 0.75);
}

.transfers-summary__clear {
    align-self: center;
    padding: 6px 14px;
    border-radius: 6px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    background: transparent;
    color: rgba(255, 255, 255, 0.35);
    font-size: 0.72rem;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.15s ease;
}

.transfers-summary__clear:hover {
    background: rgba(255, 255, 255, 0.05);
    color: rgba(255, 255, 255, 0.6);
}

/* ── Row additions ───────────────────────────────────────────────────────────── */
.compliance-transfers__row-icon {
    flex-shrink: 0;
    font-size: 0.85rem;
    width: 18px;
    text-align: center;
    line-height: 1;
}

.compliance-transfers__row-resource {
    flex-shrink: 0;
    font-size: 0.65rem;
    font-family: monospace;
    color: rgba(255, 255, 255, 0.22);
    min-width: 28px;
    text-align: center;
}

.compliance-transfers__row-risk {
    flex-shrink: 0;
    padding: 3px 9px;
    border-radius: 20px;
    font-size: 0.62rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    border: 1px solid transparent;
}

.compliance-transfers__row-risk.--high {
    background: rgba(220, 80, 80, 0.12);
    border-color: rgba(220, 80, 80, 0.28);
    color: rgba(240, 130, 120, 0.9);
}

.compliance-transfers__row-risk.--medium {
    background: rgba(220, 160, 60, 0.1);
    border-color: rgba(220, 160, 60, 0.24);
    color: rgba(230, 180, 100, 0.85);
}

.compliance-transfers__row-risk.--low {
    background: rgba(80, 168, 120, 0.08);
    border-color: rgba(80, 168, 120, 0.2);
    color: rgba(120, 200, 150, 0.75);
}

/* ── Extra category colours ──────────────────────────────────────────────────── */
.compliance-transfers__row--cmp {
    border-color: rgba(80, 168, 120, 0.12);
    background: rgba(80, 168, 120, 0.03);
}

.compliance-transfers__row-cat--cmp {
    background: rgba(80, 168, 120, 0.1);
    border-color: rgba(80, 168, 120, 0.25);
    color: rgba(120, 200, 150, 0.85);
}

.compliance-transfers__row-cat--fingerprinting {
    background: rgba(192, 54, 90, 0.12);
    border-color: rgba(192, 54, 90, 0.3);
    color: rgba(230, 120, 150, 0.9);
}

.compliance-transfers__row-cat--functional {
    background: rgba(80, 168, 120, 0.08);
    border-color: rgba(80, 168, 120, 0.2);
    color: rgba(120, 200, 150, 0.8);
}

.compliance-transfers__row-cat--cdn {
    background: rgba(150, 150, 150, 0.07);
    border-color: rgba(150, 150, 150, 0.18);
    color: rgba(180, 180, 180, 0.55);
}

.compliance-transfers__row-cat--third-party {
    background: rgba(255, 255, 255, 0.04);
    border-color: rgba(255, 255, 255, 0.1);
    color: rgba(255, 255, 255, 0.32);
}

@media (max-width: 580px) {
    .transfers-summary {
        gap: 6px;
    }

    .transfers-summary__card {
        min-width: 64px;
        padding: 10px 12px 8px;
    }

    .compliance-transfers__row-resource {
        display: none;
    }
}
